// Independent local physical witnesses. No CUDA/original/Julia algorithm includes.
#include <cmath>
#include <cstddef>
#include <cstdint>
#include <cstring>
#include <algorithm>
#include <vector>
#include <cstdio>
#include <limits>
struct P{double x,v;bool alive;};
static_assert(sizeof(P)==24&&offsetof(P,alive)==16,"particle ABI");
static constexpr long double DX=1e-4,EPS=8.85418782e-12,Q=1.602176565e-19;
static long double max_density_fraction=0,max_motion_fraction=0,max_phi_fraction=0;static uint64_t dep_values=0,motion_values=0,field_values=0;
static bool finite(long double v){return std::isfinite(v);}
static long double gamma(unsigned long long n,long double u){return n*u/(1-n*u);}
extern "C" int witness_deposition(const P*p,int n,const float*raw,const float*scaled,double weight){long double sum[101]={},mass=0;unsigned long long count[101]={};int alive=0;for(int j=0;j<n;j++)if(p[j].alive){long double pos=p[j].x,lc=pos/(long double)(double)1e-4;int i=int(lc);if(i<0||i>=100){fprintf(stderr,"Independentalivepositiondomain\n");return 1;}long double frac=lc-i;sum[i]+=1-frac;sum[i+1]+=frac;count[i]++;count[i+1]++;alive++;}
long double u32=std::ldexp(1.L,-24),u64=std::ldexp(1.L,-53);for(int i=0;i<101;i++){// Positive FP32CIC weights/additions +doublecoordinate computation interval.
 long double b=(gamma(count[i]+2,u32)+u32)*sum[i]+n*gamma(16,u64)*101+count[i]*std::numeric_limits<float>::denorm_min();long double err=fabsl((long double)raw[i]-sum[i]);if(!finite(raw[i])||err>b){fprintf(stderr,"Independentdeposition node%d err%.12Lg bound%.12Lg\n",i,err,b);return 2;}max_density_fraction=std::max(max_density_fraction,b?err/b:0.L);long double factor=(long double)weight/(long double)(double)1e-4*(i==0||i==100?2:1);long double want=(long double)raw[i]*factor;long double bs=gamma(4,u32)*fabsl(want)+gamma(8,u64)*fabsl(want)+1e-30L;if(!finite(scaled[i])||fabsl((long double)scaled[i]-want)>bs){fprintf(stderr,"Independentdensityscaling\n");return 3;}mass+=(long double)raw[i];dep_values+=2;}
 long double total_bound=gamma(2ULL*n+4,u32)*(long double)alive+n*gamma(16,u64)*101;if(fabsl(mass-alive)>total_bound){fprintf(stderr,"Independentalivecountdepositionmass\n");return 4;}return 0;}
extern "C" int witness_field(const float*ni,const float*ne,const double*rho,const double*phi,const double*ef,int converged){long double rhs[101],diag[101],solution[101];for(int i=0;i<101;i++){long double want=(long double)(double)1.602176565e-19*((long double)ni[i]-ne[i]);long double b=gamma(8,std::ldexp(1.L,-53))*(fabsl((long double)ni[i])+fabsl((long double)ne[i]))*(long double)(double)1.602176565e-19+1e-30L;if(!finite(rho[i])||fabsl(rho[i]-want)>b){fprintf(stderr,"Independentchargeequation\n");return 5;}rhs[i]=(i==0||i==100)?0:-(long double)rho[i]*(long double)(double)1e-4*(long double)(double)1e-4/(long double)(double)8.85418782e-12;diag[i]=(i==0||i==100)?1:-2;}
for(int i=1;i<101;i++){long double a=(i==100?0:1),c=(i==1?0:1),factor=a/diag[i-1];diag[i]-=factor*c;rhs[i]-=factor*rhs[i-1];}solution[100]=rhs[100]/diag[100];for(int i=99;i>=0;i--)solution[i]=(rhs[i]-(i==0?0:solution[i+1]))/diag[i];
long double maxres=0,sq=0,maxphi=1;for(int i=1;i<100;i++){long double res=-(long double)rho[i]/(long double)(double)8.85418782e-12-((long double)phi[i-1]-2*(long double)phi[i]+phi[i+1])/((long double)(double)1e-4*(long double)(double)1e-4);maxres=std::max(maxres,fabsl(res));sq+=res*res;maxphi=std::max(maxphi,fabsl((long double)phi[i]));}long double round=gamma(4096,std::ldexp(1.L,-53))*maxphi;long double bound=(100*(long double)(double)1e-4)*(100*(long double)(double)1e-4)/8*maxres+round;
if(!converged||sqrtl(sq)/101>1e-4L+gamma(4096,std::ldexp(1.L,-53))*maxphi/1e-8L){fprintf(stderr,"IndependentPoissonconvergence L2%.12Lg reported%d\n",sqrtl(sq)/101,converged);return 6;}
for(int i=0;i<101;i++){if(!finite(phi[i])||fabsl((long double)phi[i]-solution[i])>bound){fprintf(stderr,"IndependentThomasPoisson bound\n");return 7;}max_phi_fraction=std::max(max_phi_fraction,bound?fabsl(phi[i]-solution[i])/bound:0.L);long double e=i==0?-((long double)phi[1]-phi[0])/(long double)(double)1e-4:i==100?-((long double)phi[100]-phi[99])/(long double)(double)1e-4:-((long double)phi[i+1]-phi[i-1])/(2*(long double)(double)1e-4);long double be=gamma(16,std::ldexp(1.L,-53))*(1+fabsl(e)+maxphi/(long double)(double)1e-4);if(!finite(ef[i])||fabsl((long double)ef[i]-e)>be){fprintf(stderr,"Independentfieldderivative\n");return 8;}field_values+=3;}if(phi[0]!=0||phi[100]!=0)return 9;return 0;}
extern "C" int witness_motion(const P*before,const P*after,int n,const double*ef,double qm,int rewind){long double u=std::ldexp(1.L,-53);for(int j=0;j<n;j++){const auto&a=before[j];const auto&b=after[j];if(!a.alive){if(b.alive||memcmp(&a.x,&b.x,8)||memcmp(&a.v,&b.v,8))return 10;continue;}long double lc=(long double)a.x/(long double)(double)1e-4;int i=int(lc);if(i<0||i>=100)return 11;long double d=lc-i,e=(long double)ef[i]*(1-d)+(long double)ef[i+1]*d,dv=(rewind?-.5L:1.L)*(long double)(double)1e-11*(long double)qm*e,wantv=(long double)a.v+dv,bv=gamma(64,u)*(1+fabsl(a.v)+fabsl(dv)+fabsl((long double)(double)1e-11*qm)*(fabsl(ef[i])+fabsl(ef[i+1]))*101);long double ve=fabsl((long double)b.v-wantv);if(!finite(b.v)||ve>bv){fprintf(stderr,"Independentmotionv j%d err%.12Lg bound%.12Lg\n",j,ve,bv);return 12;}long double wantx=rewind?(long double)a.x:(long double)a.x+(long double)(double)1e-11*(long double)b.v,bx=gamma(32,u)*(1+fabsl(a.x)+fabsl((long double)(double)1e-11*b.v));if(!finite(b.x)||fabsl((long double)b.x-wantx)>bx){fprintf(stderr,"Independentmotionx\n");return 13;}bool flag=rewind?true:(b.x>=0&&b.x<(double)(100*1e-4));if(b.alive!=flag)return 14;max_motion_fraction=std::max(max_motion_fraction,bv?ve/bv:0.L);motion_values+=3;}return 0;}
extern "C" void witness_report(){printf("SHEATH_INDEPENDENT deposition_values=%llu motion_values=%llu field_values=%llu max_density_bound_fraction=%.12Lg max_motion_bound_fraction=%.12Lg max_phi_bound_fraction=%.12Lg\n",(unsigned long long)dep_values,(unsigned long long)motion_values,(unsigned long long)field_values,max_density_fraction,max_motion_fraction,max_phi_fraction);fflush(stdout);}
